"use client";

import { useEffect, useState } from "react";

import {
  getPipelineStatus,
  runPipeline,
  stopPipeline,
} from "@/lib/api/pipeline";

import { Button } from "@/components/ui/button";
import { Loader2, Play, Square } from "lucide-react";

export default function PipelinePage() {
  const [status, setStatus] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [stopping, setStopping] = useState(false);

  async function fetchStatus() {
    try {
      const data = await getPipelineStatus();
      setStatus(data);
    } catch (error) {
      console.error("Status fetch failed:", error);

      setStatus({
        status: "OFFLINE",
      });
    }
  }

  /* ------------------ POLLING ------------------ */

  useEffect(() => {
    fetchStatus();

    const interval = setInterval(fetchStatus, 7000);

    return () => clearInterval(interval);
  }, []);

  /* ------------------ RUN ------------------ */

  async function handleRun() {
    setLoading(true);

    try {
      await runPipeline();
      await fetchStatus();
    } catch (error) {
      console.error(error);
      alert("Failed to start pipeline");
    }

    setLoading(false);
  }

  /* ------------------ STOP ------------------ */

  async function handleStop() {
    setStopping(true);

    try {
      await stopPipeline();
      await fetchStatus();
    } catch (error) {
      console.error(error);
      alert("Failed to stop pipeline");
    }

    setStopping(false);
  }

  const isRunning = status?.status === "RUNNING";

  return (
    <div className="space-y-6 p-6">
      <h1 className="text-3xl font-bold text-white">Pipeline Control</h1>

      <div className="bg-[#222] border border-[#333] rounded-lg p-6 space-y-6 max-w-xl">
        {/* STATUS */}

        <div>
          <p className="text-gray-400 text-sm">Status</p>

          <p
            className={`text-xl font-semibold ${
              status?.status === "RUNNING"
                ? "text-yellow-400"
                : status?.status === "FAILED"
                  ? "text-red-400"
                  : status?.status === "COMPLETED"
                    ? "text-green-400"
                    : status?.status === "OFFLINE"
                      ? "text-orange-400"
                      : "text-gray-300"
            }`}
          >
            {status?.status || "UNKNOWN"}
          </p>
        </div>

        <div>
          <p className="text-gray-400 text-sm">Stage</p>
          <p className="text-white">{status?.stage || "-"}</p>
        </div>

        <div>
          <p className="text-gray-400 text-sm">Progress</p>

          <div className="w-full bg-[#333] rounded-full h-3 mt-1">
            <div
              className="bg-cyan-500 h-3 rounded-full transition-all"
              style={{ width: `${status?.progress || 0}%` }}
            />
          </div>

          <p className="text-sm text-gray-400 mt-1">
            {status?.progress ? `${Math.round(status.progress)}%` : "-"}
          </p>
        </div>

        <div>
          <p className="text-gray-400 text-sm">ETA</p>

          <p className="text-white">
            {status?.etaMinutes ? `${status.etaMinutes} minutes` : "-"}
          </p>
        </div>

        {/* START TIME */}

        <div>
          <p className="text-gray-400 text-sm">Started At</p>

          <p className="text-white">
            {status?.startedAt
              ? new Date(status.startedAt).toLocaleString()
              : "-"}
          </p>
        </div>

        {/* FINISH TIME */}

        <div>
          <p className="text-gray-400 text-sm">Last Finished</p>

          <p className="text-white">
            {status?.finishedAt
              ? new Date(status.finishedAt).toLocaleString()
              : "-"}
          </p>
        </div>

        {/* BUTTONS */}

        <div className="flex gap-4">
          <Button
            onClick={handleRun}
            disabled={loading || isRunning || stopping}
            className="bg-cyan-600 hover:bg-cyan-700 text-white gap-2"
          >
            {loading ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin" />
                Starting...
              </>
            ) : (
              <>
                <Play className="h-4 w-4" />
                Run Pipeline
              </>
            )}
          </Button>

          <Button
            onClick={handleStop}
            disabled={!isRunning || stopping}
            className="bg-red-600 hover:bg-red-700 text-white gap-2"
          >
            {stopping ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin" />
                Stopping...
              </>
            ) : (
              <>
                <Square className="h-4 w-4" />
                Stop Pipeline
              </>
            )}
          </Button>
        </div>
      </div>
    </div>
  );
}
